head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > alt]<br/>Column 의 웹접근성 향상을 위해 이미지 대체 텍스트를 설정합니다.",
    "validation" : [
        "Column 의 inputType='text', 'textImage' 일때 img 태그의 alt 속성으로 적용됩니다.",
        "문자열 설정 시, Body Cell 에 표시되는 이미지의 대체 텍스트를 설정합니다.",
        "속성값을 설정하지 않으면 Body Cell 에 alt 속성이 생성되지 않습니다.",
        "Column 이 textImageRenderType='div', inputType='textImage' 이면 이미지 영역이 button 태그로 생성되어 alt 속성이 무시됩니다.",
        "Body Cell 에 설정된 이미지를 표시할 수 없을때 대체 텍스트를 표시합니다.",
        "스크린 리더와 같은 접근성 도구가 Image 컴포넌트를 읽을때 사용됩니다.",
        "검색 엔진 크롤러에서 Body Cell 에 대한 정보를 수집할때 사용됩니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_alt.setValue("삭제 아이콘");
    con_inputType.setValue("textImage");
    con_textImageRenderType.setValue("");
    con_imageSrc.setValue("/cm/images/base/ico_grid_del.svg");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - col1 : 비교용 text Column
//  - col2 : 검증 대상 Column (alt / inputType / textImageRenderType / imageSrc 를 옵션값으로 설정, viewType="icon" 고정)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    let cAlt = con_alt.getValue();
    let cInputType = con_inputType.getValue();
    let cRenderType = con_textImageRenderType.getValue();
    let cImageSrc = con_imageSrc.getValue();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 검증 대상은 col2 Column (viewType=icon 고정), col1 은 비교용 text Column\n[확인] alt 확인 -> Row 0 col2 Body Cell 의 이미지 요소 / alt 속성 / 이미지 표시 상태\n[확인] 존재하지 않는 이미지 경로 선택 시 화면의 col2 셀에 대체 텍스트가 보이는지 함께 확인"', '', 'label1');

    // dataList 생성 (col1~col4 / 4행)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // inputType=image 는 Cell 데이터를 이미지 경로로 사용하므로 col2 데이터를 imageSrc 옵션 경로로 설정
    if (cInputType === 'image') {
        for (let i = 0; i < dlt_bind.getRowCount(); i++) {
            dlt_bind.setCellData(i, "col2", cImageSrc);
        }
    }

    // col2 Column 속성 (미설정 옵션은 속성 자체를 넣지 않는다)
    let attrCol2 = ' inputType="' + cInputType + '" viewType="icon" imageSrc="' + cImageSrc + '"';
    if (cRenderType !== '') {
        attrCol2 += ' textImageRenderType="' + cRenderType + '"';
    }
    if (cAlt !== '') {
        attrCol2 += ' alt="' + cAlt + '"';
    }

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:500px;height:180px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="300" style="" inputType="text" id="column2" value="name2 (alt)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="300" style="" id="col2" value=""' + attrCol2 + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// Row 0 col2 Body Cell 의 이미지 요소 / alt 속성 / 표시 상태 확인
//  - validation 1, 2, 3, 6, 7 : 이미지 요소 종류와 alt 속성 유무·값 (접근성 도구·크롤러가 읽는 마크업 속성)
//  - validation 4 : textImageRenderType=div 이면 BUTTON 요소 + alt 속성 없음
//  - validation 5 : 이미지 로드 실패 시 대체 텍스트가 셀에 표시되는지 (로드 확정 후 naturalWidth 와 렌더 박스 크기)
//    대체 텍스트 표시 시 셀 데이터 값을 함께 출력 (셀 값 대신 alt 가 보이는지 화면과 대비)
scwin.btn_getAlt_onclick = async function () {
    let bottom = wf_body_bottom.getObj("scwin");

    let td = document.querySelector("td[id*='target1_cell_0_1']");
    let img = td ? td.querySelector("img") : null;
    let btn = td ? td.querySelector("button") : null;

    if (!img && !btn) {
        bottom.setReturnValue("이미지 요소 없음 / Body Cell 텍스트 : " + (td ? td.textContent : ""));
        return;
    }

    let elem = img || btn;
    let strAlt = elem.hasAttribute("alt") ? "alt 속성 : " + elem.getAttribute("alt") : "alt 속성 없음";

    if (btn) {
        let strAria = btn.hasAttribute("aria-label") ? btn.getAttribute("aria-label") : "없음";
        let strTitle = btn.hasAttribute("title") ? btn.getAttribute("title") : "없음";
        bottom.setReturnValue("이미지 요소 : BUTTON / " + strAlt + " / aria-label : " + strAria + " / title : " + strTitle);
        return;
    }

    bottom.setReturnValue("이미지 요소 : IMG / " + strAlt);

    // 로드 성공 / 실패가 확정된 뒤 표시 상태를 판정한다
    if (!img.complete) {
        await new Promise(function (resolve) {
            img.addEventListener("load", resolve, { once : true });
            img.addEventListener("error", resolve, { once : true });
            setTimeout(resolve, 2000);
        });
    }

    let loaded = img.complete && img.naturalWidth > 0;
    let strBox = " (렌더 박스 " + img.offsetWidth + " x " + img.offsetHeight + ")";

    if (loaded) {
        bottom.setReturnValue("이미지 로드 성공 -> 이미지 표시" + strBox);
    } else if (img.hasAttribute("alt") && img.getAttribute("alt") !== "") {
        bottom.setReturnValue("이미지 로드 실패 -> 대체 텍스트 표시" + strBox + " / 셀 값 : " + dlt_bind.getCellData(0, "col2"));
    } else {
        bottom.setReturnValue("이미지 로드 실패 -> 대체 텍스트 없음" + strBox);
    }
}
